package lucas.labendzs.myapplication.database

import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteOpenHelper

/**
 * Gerenciador do banco de dados SQLite para armazenar filmes/séries.
 * Estende SQLiteOpenHelper, responsável por criar e manter o esquema do banco.
 *
 * @param context Contexto da aplicação
 */
class FilmeDBHelper(context: Context) : SQLiteOpenHelper(
    context,
    DATABASE_NAME,   // Nome do arquivo do banco
    null,            // factory (não usado, deixar null)
    DATABASE_VERSION // Versão do banco
) {

    companion object {
        // Nome do arquivo do banco de dados
        private const val DATABASE_NAME = "filme.db"

        // Versão do banco (alterar quando mudar o esquema)
        private const val DATABASE_VERSION = 1

        // Nome da tabela
        const val TABLE_NAME = "filmes"

        // Nomes das colunas
        const val COLUMN_ID = "id"
        const val COLUMN_NOME = "nome"
        const val COLUMN_TIPO = "tipo"
        const val COLUMN_IMAGEM = "imagem"
        const val COLUMN_ASSISTIDO = "assistido"
        const val COLUMN_DATA_ASSISTIDO = "data_assistido"
    }

    /**
     * Chamado quando o banco é criado pela primeira vez.
     * Aqui definimos a estrutura da tabela.
     *
     * @param db Instância do banco de dados
     */
    override fun onCreate(db: SQLiteDatabase) {
        // SQL para criar a tabela "filmes"
        val createTableSQL = """
            CREATE TABLE $TABLE_NAME (
                $COLUMN_ID INTEGER PRIMARY KEY AUTOINCREMENT,
                $COLUMN_NOME TEXT NOT NULL,
                $COLUMN_TIPO TEXT NOT NULL,
                $COLUMN_IMAGEM TEXT,
                $COLUMN_ASSISTIDO INTEGER NOT NULL DEFAULT 0,
                $COLUMN_DATA_ASSISTIDO TEXT
            )
        """.trimIndent()

        db.execSQL(createTableSQL)
    }

    /**
     * Chamado quando a versão do banco é alterada.
     * Aqui fazemos modificações no esquema (adicionar coluna, mudar tipo, etc).
     *
     * @param db Instância do banco de dados
     * @param oldVersion Versão anterior
     * @param newVersion Nova versão
     */
    override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) {
        // Neste projeto, usamos apenas versão 1, então este método não será executado
        // Mas deixamos aqui como padrão para expansões futuras

        // Exemplo de upgrade (se houvesse):
        // if (oldVersion < 2) {
        //     db.execSQL("ALTER TABLE $TABLE_NAME ADD COLUMN coluna_nova TEXT")
        // }
    }
}

package lucas.labendzs.myapplication.database
import android.content.Context import android.database.sqlite.SQLiteDatabase import android.database.sqlite.SQLiteOpenHelper
class FilmeDBHelper(context: Context) : SQLiteOpenHelper( context, DATABASE_NAME, null, DATABASE_VERSION ) {
companion object { private const val DATABASE_NAME = "filme.db" private const val DATABASE_VERSION = 1 const val TABLE_NAME = "filmes" const val COLUMN_ID = "id" const val COLUMN_NOME = "nome" const val COLUMN_TIPO = "tipo" const val COLUMN_IMAGEM = "imagem" const val COLUMN_ASSISTIDO = "assistido" const val COLUMN_DATA_ASSISTIDO = "data_assistido" }
override fun onCreate(db: SQLiteDatabase) { val createTableSQL = """ CREATE TABLE $TABLE_NAME ( $COLUMN_ID INTEGER PRIMARY KEY AUTOINCREMENT, $COLUMN_NOME TEXT NOT NULL, $COLUMN_TIPO TEXT NOT NULL, $COLUMN_IMAGEM TEXT, $COLUMN_ASSISTIDO INTEGER NOT NULL DEFAULT 0, $COLUMN_DATA_ASSISTIDO TEXT ) """.trimIndent()
db.execSQL(createTableSQL) }
override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) { } }
